def forward(groups):
    is_less_than = 1 if groups[0] else 0
    value = int(groups[1].strip())
    is_seconds = 1 if groups[3] == 'sec' else 0
    seconds = value if is_seconds else value * 60 + int(groups[3][1:])
    return {'stored': [seconds], 'layout': [is_less_than, is_seconds]}

def inverse(record):
    seconds = int(record['stored'][0])
    layout = record.get('layout', [])
    is_less_than = layout[0]
    is_seconds = layout[1]
    if is_less_than:
        return '<1 sec'
    if is_seconds:
        return str(seconds) + ' sec'
    minutes = seconds // 60
    remaining_seconds = seconds % 60
    return str(minutes).zfill(2) + ':' + str(remaining_seconds).zfill(2)
